import { Router } from "express";
import { authRouter, requireAuth } from "./auth";
import { healthRouter } from "./health";
import { reportsRouter } from "./reports";
import { uploadsRouter } from "./uploads";
import { usersRouter } from "./users";

export const apiRouter = Router();

// Public
apiRouter.use("/health", healthRouter);
apiRouter.use("/auth", authRouter);

// Everything below needs a bearer token.
apiRouter.use("/users", requireAuth, usersRouter);
apiRouter.use("/uploads", requireAuth, uploadsRouter);
apiRouter.use("/reports", requireAuth, reportsRouter);
--- src/api/uploads.ts
import { randomUUID } from "crypto";
import { Router, type NextFunction, type Request, type Response } from "express";
import multer from "multer";
import { z } from "zod";
import { config } from "../config";
import { db } from "../db/client";
import { pickLocale, t } from "../i18n";
import { OPTIONAL_COLUMNS, parseStatement, REQUIRED_COLUMNS } from "../ingest/parser";
import { createUploadWithJob, findUpload } from "../ingest/queue";
import { storage, uploadKey } from "../storage";
import { currentUser } from "./auth";
import { asyncHandler, HttpError, notFoundError } from "./errors";

// Browsers disagree on the MIME type of a .csv file, so the extension is checked too.
const ACCEPTED_TYPES = new Set(["text/csv", "application/csv", "application/vnd.ms-excel", "text/plain"]);
const PREVIEW_ROWS = 5;
const KNOWN_COLUMNS = new Set([...REQUIRED_COLUMNS, ...OPTIONAL_COLUMNS]);

const upload = multer({
  storage: multer.memoryStorage(),
  limits: { fileSize: config.uploads.maxBytes, files: 1 },
});

const bodySchema = z.object({
  accountId: z.string().uuid(),
});

export const uploadsRouter = Router();

// Turn multer's size error into a translated 413 instead of a 500.
function handleMulterErrors(err: unknown, req: Request, res: Response, next: NextFunction): void {
  if (err instanceof multer.MulterError && err.code === "LIMIT_FILE_SIZE") {
    const limit = Math.round(config.uploads.maxBytes / (1024 * 1024));
    const locale = pickLocale(req.header("accept-language"));
    res.status(413).json({ error: t("errors.fileTooLarge", { limit }, locale) });
    return;
  }
  next(err);
}

async function assertOwnsAccount(accountId: string, userId: string): Promise<void> {
  const row = await db.maybeOne<{ id: string }>(
    "SELECT id FROM accounts WHERE id = $1 AND user_id = $2",
    [accountId, userId],
  );
  if (!row) throw notFoundError("account");
}

uploadsRouter.post(
  "/",
  upload.single("file"),
  handleMulterErrors,
  asyncHandler(async (req, res) => {
    const user = currentUser(req);
    const { accountId } = bodySchema.parse(req.body);
    await assertOwnsAccount(accountId, user.id);

    const file = req.file;
    if (!file) throw new HttpError(400, "file is required");
    if (!file.originalname.toLowerCase().endsWith(".csv") || !ACCEPTED_TYPES.has(file.mimetype)) {
      throw new HttpError(415, t("errors.unsupportedFileType", {}, pickLocale(req.header("accept-language"))));
    }

    // Parse the first few rows now so a broken file is rejected before it is stored and queued.
    const preview = parseStatement(file.buffer, { limit: PREVIEW_ROWS });

    const id = randomUUID();
    const key = uploadKey(accountId, id, file.originalname);
    await storage.put(key, file.buffer, "text/csv");
    await createUploadWithJob({
      id,
      accountId,
      userId: user.id,
      key,
      filename: file.originalname,
      sizeBytes: file.size,
    });

    res.status(202).json({
      id,
      status: "pending",
      columns: preview.header,
      ignoredColumns: preview.header.filter((column) => !KNOWN_COLUMNS.has(column)),
      preview: preview.rows,
    });
  }),
);

uploadsRouter.get(
  "/:id",
  asyncHandler(async (req, res) => {
    const found = await findUpload(req.params.id, currentUser(req).id);
    if (!found) throw notFoundError("upload");

    const locale = pickLocale(req.header("accept-language"));
    res.json({
      id: found.id,
      filename: found.filename,
      status: found.status,
      inserted: found.insertedCount,
      duplicates: found.duplicateCount,
      error: found.errorKey ? t(found.errorKey, found.errorParams ?? {}, locale) : null,
      row: found.errorParams?.row ?? null,
      createdAt: found.createdAt,
      finishedAt: found.finishedAt,
    });
  }),
);
--- src/api/users.ts
import { Router } from "express";
import { z } from "zod";
import { userRepo } from "../db/repos/userRepo";
import { LOCALES } from "../i18n";
import type { PublicUser, User } from "../types";
import { isValidTimeZone } from "../util/dates";
import { currentUser } from "./auth";
import { asyncHandler, notFoundError } from "./errors";

export const usersRouter = Router();

function toPublic({ passwordHash: _passwordHash, ...rest }: User): PublicUser {
  return rest;
}

const profileSchema = z
  .object({
    name: z.string().min(1).max(100).optional(),
    locale: z.enum(LOCALES).optional(),
    timezone: z.string().refine(isValidTimeZone, "unknown time zone").optional(),
    weeklyRollup: z.boolean().optional(),
  })
  .strict();

usersRouter.get(
  "/me",
  asyncHandler(async (req, res) => {
    const user = await userRepo.findById(currentUser(req).id);
    if (!user) throw notFoundError("user");
    res.json(toPublic(user));
  }),
);

usersRouter.patch(
  "/me",
  asyncHandler(async (req, res) => {
    const patch = profileSchema.parse(req.body);
    const user = await userRepo.updateProfile(currentUser(req).id, patch);
    if (!user) throw notFoundError("user");
    res.json(toPublic(user));
  }),
);
--- src/components/DateRangePicker.tsx
import { useEffect, useState } from "react";
import { t, type Locale } from "../i18n";
import { addDays, toISODate } from "../util/dates";

export interface DateRange {
  /** YYYY-MM-DD */
  from: string;
  /** YYYY-MM-DD */
  to: string;
}

interface DateRangePickerProps {
  value: DateRange;
  onChange: (range: DateRange) => void;
  locale?: Locale;
}

function thisMonth(today = new Date()): DateRange {
  const first = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), 1));
  return { from: toISODate(first), to: toISODate(today) };
}

function lastDays(days: number, today = new Date()): DateRange {
  return { from: toISODate(addDays(today, -(days - 1))), to: toISODate(today) };
}

export function DateRangePicker({ value, onChange, locale = "en" }: DateRangePickerProps) {
  // Local draft so a half-edited range is not pushed to the parent.
  const [draft, setDraft] = useState<DateRange>(value);

  // Depend on the strings, not the object, so a parent re-render does not reset the draft.
  useEffect(() => {
    setDraft({ from: value.from, to: value.to });
  }, [value.from, value.to]);

  const invalid = draft.from !== "" && draft.to !== "" && draft.from > draft.to;

  const update = (patch: Partial<DateRange>) => {
    const next = { ...draft, ...patch };
    setDraft(next);
    if (next.from && next.to && next.from <= next.to) onChange(next);
  };

  const applyPreset = (range: DateRange) => {
    setDraft(range);
    onChange(range);
  };

  return (
    <fieldset className="date-range">
      <label>
        {t("ui.dateRange.from", {}, locale)}
        <input
          type="date"
          value={draft.from}
          max={draft.to || undefined}
          onChange={(e) => update({ from: e.target.value })}
        />
      </label>
      <label>
        {t("ui.dateRange.to", {}, locale)}
        <input
          type="date"
          value={draft.to}
          min={draft.from || undefined}
          onChange={(e) => update({ to: e.target.value })}
        />
      </label>

      <div className="date-range__presets">
        <button type="button" onClick={() => applyPreset(thisMonth())}>
          {t("ui.dateRange.thisMonth", {}, locale)}
        </button>
        <button type="button" onClick={() => applyPreset(lastDays(30))}>
          {t("ui.dateRange.last30", {}, locale)}
        </button>
      </div>

      {invalid && (
        <p className="date-range__error" role="alert">
          {t("ui.dateRange.invalid", {}, locale)}
        </p>
      )}
    </fieldset>
  );
}
--- src/components/ExportButton.tsx
import { useState } from "react";
import { SUPPORTED_FORMATS, type ExportFormat } from "../exportUtils";
import { t } from "../i18n";
import { useToast } from "./Toast";

const TOKEN_KEY = "ledgerline.token";

function authHeader(): Record<string, string> {
  const token = sessionStorage.getItem(TOKEN_KEY);
  return token ? { authorization: `Bearer ${token}` } : {};
}

function filenameFromDisposition(header: string | null): string | null {
  const match = header?.match(/filename="([^"]+)"/);
  return match ? match[1] : null;
}

/** Downloads the export through a temporary object URL. Rejects on a non-2xx response. */
export async function exportReport(reportId: string, format: ExportFormat): Promise<void> {
  const res = await fetch(`/api/v1/reports/${encodeURIComponent(reportId)}/export?format=${format}`, {
    headers: authHeader(),
  });
  if (!res.ok) {
    throw new Error(`export failed with status ${res.status}`);
  }

  const blob = await res.blob();
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filenameFromDisposition(res.headers.get("content-disposition")) ?? `report.${format}`;
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

interface ExportButtonProps {
  reportId: string;
  defaultFormat?: ExportFormat;
}

export function ExportButton({ reportId, defaultFormat = "csv" }: ExportButtonProps) {
  const [busy, setBusy] = useState(false);
  const [format, setFormat] = useState<ExportFormat>(defaultFormat);
  const toast = useToast();

  const handleClick = () => {
    setBusy(true);
    exportReport(reportId, format).then(() => {
      setBusy(false);
      toast.show(t("ui.export.done"), "success");
    });
  };

  return (
    <div className="export-button">
      <select
        aria-label={t("ui.export.format")}
        value={format}
        disabled={busy}
        onChange={(e) => setFormat(e.target.value as ExportFormat)}
      >
        {SUPPORTED_FORMATS.map((f) => (
          <option key={f} value={f}>
            {f.toUpperCase()}
          </option>
        ))}
      </select>
      <button type="button" onClick={handleClick} disabled={busy}>
        {busy ? t("ui.export.busy") : t("ui.export.button")}
      </button>
    </div>
  );
}
