import { useEffect, useState } from "react";
import { t, type Locale } from "../i18n";
import { addDays, toISODate } from "../util/dates";

export interface DateRange {
  /** YYYY-MM-DD */
  from: string;
  /** YYYY-MM-DD */
  to: string;
}

interface DateRangePickerProps {
  value: DateRange;
  onChange: (range: DateRange) => void;
  locale?: Locale;
}

function thisMonth(today = new Date()): DateRange {
  const first = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), 1));
  return { from: toISODate(first), to: toISODate(today) };
}

function lastDays(days: number, today = new Date()): DateRange {
  return { from: toISODate(addDays(today, -(days - 1))), to: toISODate(today) };
}

export function DateRangePicker({ value, onChange, locale = "en" }: DateRangePickerProps) {
  // Local draft so a half-edited range is not pushed to the parent.
  const [draft, setDraft] = useState<DateRange>(value);

  // Depend on the strings, not the object, so a parent re-render does not reset the draft.
  useEffect(() => {
    setDraft({ from: value.from, to: value.to });
  }, [value.from, value.to]);

  const invalid = draft.from !== "" && draft.to !== "" && draft.from > draft.to;

  const update = (patch: Partial<DateRange>) => {
    const next = { ...draft, ...patch };
    setDraft(next);
    if (next.from && next.to && next.from <= next.to) onChange(next);
  };

  const applyPreset = (range: DateRange) => {
    setDraft(range);
    onChange(range);
  };

  return (
    <fieldset className="date-range">
      <label>
        {t("ui.dateRange.from", {}, locale)}
        <input
          type="date"
          value={draft.from}
          max={draft.to || undefined}
          onChange={(e) => update({ from: e.target.value })}
        />
      </label>
      <label>
        {t("ui.dateRange.to", {}, locale)}
        <input
          type="date"
          value={draft.to}
          min={draft.from || undefined}
          onChange={(e) => update({ to: e.target.value })}
        />
      </label>

      <div className="date-range__presets">
        <button type="button" onClick={() => applyPreset(thisMonth())}>
          {t("ui.dateRange.thisMonth", {}, locale)}
        </button>
        <button type="button" onClick={() => applyPreset(lastDays(30))}>
          {t("ui.dateRange.last30", {}, locale)}
        </button>
      </div>

      {invalid && (
        <p className="date-range__error" role="alert">
          {t("ui.dateRange.invalid", {}, locale)}
        </p>
      )}
    </fieldset>
  );
}
--- src/components/ExportButton.tsx
import { useState } from "react";
import { SUPPORTED_FORMATS, type ExportFormat } from "../exportUtils";
import { t } from "../i18n";
import { useToast } from "./Toast";

const TOKEN_KEY = "ledgerline.token";

function authHeader(): Record<string, string> {
  const token = sessionStorage.getItem(TOKEN_KEY);
  return token ? { authorization: `Bearer ${token}` } : {};
}

function filenameFromDisposition(header: string | null): string | null {
  const match = header?.match(/filename="([^"]+)"/);
  return match ? match[1] : null;
}

/** Downloads the export through a temporary object URL. Rejects on a non-2xx response. */
export async function exportReport(reportId: string, format: ExportFormat): Promise<void> {
  const res = await fetch(`/api/v1/reports/${encodeURIComponent(reportId)}/export?format=${format}`, {
    headers: authHeader(),
  });
  if (!res.ok) {
    throw new Error(`export failed with status ${res.status}`);
  }

  const blob = await res.blob();
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filenameFromDisposition(res.headers.get("content-disposition")) ?? `report.${format}`;
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

interface ExportButtonProps {
  reportId: string;
  defaultFormat?: ExportFormat;
}

export function ExportButton({ reportId, defaultFormat = "csv" }: ExportButtonProps) {
  const [busy, setBusy] = useState(false);
  const [format, setFormat] = useState<ExportFormat>(defaultFormat);
  const toast = useToast();

  const handleClick = () => {
    setBusy(true);
    exportReport(reportId, format).then(() => {
      setBusy(false);
      toast.show(t("ui.export.done"), "success");
    });
  };

  return (
    <div className="export-button">
      <select
        aria-label={t("ui.export.format")}
        value={format}
        disabled={busy}
        onChange={(e) => setFormat(e.target.value as ExportFormat)}
      >
        {SUPPORTED_FORMATS.map((f) => (
          <option key={f} value={f}>
            {f.toUpperCase()}
          </option>
        ))}
      </select>
      <button type="button" onClick={handleClick} disabled={busy}>
        {busy ? t("ui.export.busy") : t("ui.export.button")}
      </button>
    </div>
  );
}
