import { reportRepo } from "../db/repos/reportRepo";
import { transactionRepo } from "../db/repos/transactionRepo";
import { formatExportFilename, type ExportFormat } from "../exportUtils";
import { logger } from "../logger";
import { sendEmail } from "../notifications/email";
import { scheduledExportEmail } from "../notifications/templates";
import type { Cadence, Report, ReportRow } from "../types";
import { writeCsv, type ExportFile } from "./csv";
import { writeXlsx } from "./xlsx";

const TICK_MS = 5 * 60 * 1000;
/** Scheduled exports go out at this hour, UTC. */
const RUN_HOUR_UTC = 6;

const writers: Record<ExportFormat, (rows: ReportRow[]) => ExportFile | Promise<ExportFile>> = {
  csv: (rows) => writeCsv(rows),
  xlsx: (rows) => writeXlsx(rows),
};

/** The next run strictly after `from`. Monthly runs go out on the 1st. */
export function nextRunAt(cadence: Cadence, from: Date): Date {
  const next = new Date(from.getTime());
  next.setUTCHours(RUN_HOUR_UTC, 0, 0, 0);
  switch (cadence) {
    case "daily":
      if (next <= from) next.setUTCDate(next.getUTCDate() + 1);
      break;
    case "weekly":
      next.setUTCDate(next.getUTCDate() + 7);
      break;
    case "monthly":
      next.setUTCMonth(next.getUTCMonth() + 1, 1);
      break;
  }
  return next;
}

async function runScheduledExport(report: Report, now: Date): Promise<void> {
  const schedule = report.schedule;
  if (!schedule) return;

  const rows = await transactionRepo.listForReport(report);
  const file = await writers[schedule.format](rows);
  const filename = formatExportFilename(report.name, schedule.format, now);

  await sendEmail({
    ...scheduledExportEmail(report, schedule.recipients, rows.length),
    attachments: [{ filename, content: file.body, contentType: file.contentType }],
  });
  await reportRepo.markScheduleRun(report.id, nextRunAt(schedule.cadence, now));
}

/** Runs every export whose next_run_at has passed. Returns how many were sent. */
export async function runDueExports(now: Date = new Date()): Promise<number> {
  const due = await reportRepo.listDueSchedules(now);
  let sent = 0;
  for (const report of due) {
    try {
      await runScheduledExport(report, now);
      sent += 1;
    } catch (err) {
      // Left due, so the next tick tries again.
      logger.error({ err, reportId: report.id }, "scheduled export failed");
    }
  }
  return sent;
}

export function startExportScheduler(): () => void {
  let running = false;
  const timer = setInterval(() => {
    if (running) return;
    running = true;
    runDueExports()
      .then((sent) => {
        if (sent > 0) logger.info({ sent }, "scheduled exports sent");
      })
      .catch((err) => logger.error({ err }, "export scheduler tick failed"))
      .finally(() => {
        running = false;
      });
  }, TICK_MS);
  return () => clearInterval(timer);
}
--- src/export/xlsx.ts
import ExcelJS from "exceljs";
import { COLUMN_LABELS, COLUMN_ORDER, CONTENT_TYPES, type ExportColumn } from "../exportUtils";
import type { ReportRow } from "../types";
import { minorDigits, toMajor } from "../util/money";
import type { ExportFile } from "./csv";

const COLUMN_WIDTHS: Record<ExportColumn, number> = {
  date: 12,
  amount: 14,
  currency: 10,
  description: 48,
  category: 20,
};

function amountFormat(currency: string): string {
  return minorDigits(currency) === 0 ? "#,##0" : "#,##0.00";
}

export async function writeXlsx(rows: readonly ReportRow[], sheetName = "Transactions"): Promise<ExportFile> {
  const workbook = new ExcelJS.Workbook();
  workbook.creator = "Ledgerline";
  workbook.created = new Date();

  const sheet = workbook.addWorksheet(sheetName, {
    views: [{ state: "frozen", ySplit: 1 }],
  });
  sheet.columns = COLUMN_ORDER.map((key) => ({
    header: COLUMN_LABELS[key],
    key,
    width: COLUMN_WIDTHS[key],
  }));
  sheet.getRow(1).font = { bold: true };

  for (const row of rows) {
    const added = sheet.addRow({
      // Midnight UTC so the cell shows the same calendar date everywhere.
      date: new Date(`${row.date}T00:00:00Z`),
      amount: toMajor(row.amount, row.currency),
      currency: row.currency,
      description: row.description,
      category: row.category ?? "",
    });
    added.getCell("amount").numFmt = amountFormat(row.currency);
  }

  sheet.getColumn("date").numFmt = "yyyy-mm-dd";
  sheet.autoFilter = {
    from: { row: 1, column: 1 },
    to: { row: 1, column: COLUMN_ORDER.length },
  };

  const buffer = await workbook.xlsx.writeBuffer();
  return { body: Buffer.from(buffer as ArrayBuffer), contentType: CONTENT_TYPES.xlsx };
}
--- src/exportUtils.ts
import type { ReportRow } from "./types";
import { formatMinor } from "./util/money";
import { slugify } from "./util/strings";

export const SUPPORTED_FORMATS = ["csv", "xlsx"] as const;

export type ExportFormat = (typeof SUPPORTED_FORMATS)[number];

export function isSupportedFormat(value: unknown): value is ExportFormat {
  return typeof value === "string" && (SUPPORTED_FORMATS as readonly string[]).includes(value);
}

export const CONTENT_TYPES: Record<ExportFormat, string> = {
  csv: "text/csv; charset=utf-8",
  xlsx: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
};

// Since 3.2.0 date comes first, which is what most accounting tools expect on import.
export const COLUMN_ORDER = ["date", "amount", "currency", "description", "category"] as const;

export type ExportColumn = (typeof COLUMN_ORDER)[number];

export const COLUMN_LABELS: Record<ExportColumn, string> = {
  date: "Date",
  amount: "Amount",
  currency: "Currency",
  description: "Description",
  category: "Category",
};

const NEEDS_QUOTES = /[",\n]/;

/** Quotes a field when it contains a delimiter, a quote or a newline. */
export function escapeField(value: string): string {
  return NEEDS_QUOTES.test(value) ? `"${value.replace(/"/g, '""')}"` : value;
}

function cellValue(row: ReportRow, column: ExportColumn): string {
  switch (column) {
    case "amount":
      return formatMinor(row.amount, row.currency);
    case "category":
      return row.category ?? "";
    default:
      return row[column];
  }
}

/** A header line followed by one line per row, in the given column order. */
export function toDelimited(rows: readonly ReportRow[], columns: readonly ExportColumn[] = COLUMN_ORDER): string {
  const lines = [columns.map((column) => escapeField(COLUMN_LABELS[column])).join(",")];
  for (const row of rows) {
    lines.push(columns.map((column) => escapeField(cellValue(row, column))).join(","));
  }
  return lines.join("\n") + "\n";
}

/** "March expenses" + csv -> "march-expenses-2026-04-01.csv" */
export function formatExportFilename(reportName: string, format: ExportFormat, at: Date = new Date()): string {
  const base = slugify(reportName) || "report";
  return `${base}-${at.toISOString().slice(0, 10)}.${format}`;
}
