export function ExportButton({ reportId, defaultFormat = "csv" }: ExportButtonProps) {
  const [busy, setBusy] = useState(false);
  const [format, setFormat] = useState<ExportFormat>(defaultFormat);
  const toast = useToast();

  const handleClick = () => {
    setBusy(true);
