import { config } from "../config";
import { db } from "../db/client";
import type { Upload, UploadStatus } from "../types";
import { backoffDelay } from "../util/retry";
import type { IngestErrorParams } from "./errors";

/**
 * Import jobs live in Postgres (table import_jobs), one per upload. Workers
 * claim them with FOR UPDATE SKIP LOCKED, so any number of processes can poll.
 */

export interface ImportJob {
  id: string;
  /** Includes the attempt currently running. */
  attempts: number;
  upload: Upload;
}

export interface NewUpload {
  id: string;
  accountId: string;
  userId: string;
  key: string;
  filename: string;
  sizeBytes: number;
}

export interface JobFailure {
  message: string;
  key?: string;
  params?: IngestErrorParams;
}

interface UploadRecord {
  id: string;
  account_id: string;
  user_id: string;
  storage_key: string;
  filename: string;
  size_bytes: number;
  status: UploadStatus;
  default_currency: string;
  error_key: string | null;
  error_params: IngestErrorParams | null;
  inserted_count: number | null;
  duplicate_count: number | null;
  created_at: Date;
  finished_at: Date | null;
}

const UPLOAD_COLUMNS = `u.id, u.account_id, u.user_id, u.storage_key, u.filename, u.size_bytes, u.status,
  a.default_currency, u.error_key, u.error_params, u.inserted_count, u.duplicate_count,
  u.created_at, u.finished_at`;

function toUpload(row: UploadRecord): Upload {
  return {
    id: row.id,
    accountId: row.account_id,
    userId: row.user_id,
    key: row.storage_key,
    filename: row.filename,
    sizeBytes: row.size_bytes,
    status: row.status,
    defaultCurrency: row.default_currency,
    errorKey: row.error_key,
    errorParams: row.error_params,
    insertedCount: row.inserted_count,
    duplicateCount: row.duplicate_count,
    createdAt: row.created_at,
    finishedAt: row.finished_at,
  };
}

export async function createUploadWithJob(input: NewUpload): Promise<void> {
  await db.tx(async (q) => {
    await q.query(
      `INSERT INTO uploads (id, account_id, user_id, storage_key, filename, size_bytes)
       VALUES ($1, $2, $3, $4, $5, $6)`,
      [input.id, input.accountId, input.userId, input.key, input.filename, input.sizeBytes],
    );
    await q.query("INSERT INTO import_jobs (upload_id) VALUES ($1)", [input.id]);
  });
}

export async function findUpload(id: string, userId: string): Promise<Upload | null> {
  const row = await db.maybeOne<UploadRecord>(
    `SELECT ${UPLOAD_COLUMNS} FROM uploads u JOIN accounts a ON a.id = u.account_id
      WHERE u.id = $1 AND u.user_id = $2`,
    [id, userId],
  );
  return row ? toUpload(row) : null;
}

export async function claimNext(): Promise<ImportJob | null> {
  return db.tx(async (q) => {
    const [job] = await q.query<{ id: string; attempts: number; upload_id: string }>(
      `SELECT id, attempts, upload_id FROM import_jobs
        WHERE status = 'pending' AND run_after <= now()
        ORDER BY run_after
        FOR UPDATE SKIP LOCKED
        LIMIT 1`,
    );
    if (!job) return null;

    await q.query("UPDATE import_jobs SET status = 'running', attempts = attempts + 1 WHERE id = $1", [job.id]);
    const [upload] = await q.query<UploadRecord>(
      `UPDATE uploads u SET status = 'importing' FROM accounts a
        WHERE u.id = $1 AND a.id = u.account_id
        RETURNING ${UPLOAD_COLUMNS}`,
      [job.upload_id],
    );
    return { id: job.id, attempts: job.attempts + 1, upload: toUpload(upload) };
  });
}

export async function completeJob(job: ImportJob, counts: { inserted: number; duplicates: number }): Promise<void> {
  await db.tx(async (q) => {
    await q.query("UPDATE import_jobs SET status = 'done', last_error = NULL WHERE id = $1", [job.id]);
    await q.query(
      `UPDATE uploads SET status = 'imported', inserted_count = $2, duplicate_count = $3, finished_at = now()
        WHERE id = $1`,
      [job.upload.id, counts.inserted, counts.duplicates],
    );
  });
}

/**
 * Reschedules the job with backoff, or marks it (and its upload) failed when it
 * is not retryable or has used all its attempts. Returns true when final.
 */
export async function failJob(job: ImportJob, failure: JobFailure, retryable: boolean): Promise<boolean> {
  const final = !retryable || job.attempts >= config.queue.maxAttempts;

  await db.tx(async (q) => {
    if (final) {
      await q.query("UPDATE import_jobs SET status = 'failed', last_error = $2 WHERE id = $1", [
        job.id,
        failure.message,
      ]);
      await q.query(
        `UPDATE uploads SET status = 'failed', error_key = $2, error_params = $3, finished_at = now()
          WHERE id = $1`,
        [job.upload.id, failure.key ?? null, failure.params ?? null],
      );
      return;
    }
    const delayMs = backoffDelay(job.attempts, 5_000, 10 * 60_000);
    await q.query(
      `UPDATE import_jobs SET status = 'pending', last_error = $2, run_after = now() + $3 * interval '1 millisecond'
        WHERE id = $1`,
      [job.id, failure.message, delayMs],
    );
    await q.query("UPDATE uploads SET status = 'pending' WHERE id = $1", [job.upload.id]);
  });

  return final;
}

export async function listFailedUploadsBefore(cutoff: Date, limit = 500): Promise<Pick<Upload, "id" | "key">[]> {
  const rows = await db.query<{ id: string; storage_key: string }>(
    "SELECT id, storage_key FROM uploads WHERE status = 'failed' AND finished_at < $1 ORDER BY finished_at LIMIT $2",
    [cutoff, limit],
  );
  return rows.map((row) => ({ id: row.id, key: row.storage_key }));
}

export async function markUploadPurged(id: string): Promise<void> {
  await db.query("UPDATE uploads SET status = 'purged' WHERE id = $1", [id]);
}

/** Runnable jobs only; finished and failed jobs do not count. */
export async function queueDepth(): Promise<number> {
  const row = await db.one<{ count: number }>(
    "SELECT count(*)::int AS count FROM import_jobs WHERE status IN ('pending', 'running')",
  );
  return row.count;
}
--- src/ingest/schema.ts
import { z } from "zod";
import type { IncomingTransaction } from "../types";
import { parseStatementDate } from "../util/dates";
import { isCurrencyCode, parseAmount } from "../util/money";
import { normalizeDescription } from "../util/strings";
import { IngestError } from "./errors";
import type { RawRow } from "./parser";

const rawRowSchema = z.object({
  date: z.string(),
  amount: z.string(),
  description: z.string(),
  currency: z.string().optional(),
  category: z.string().optional(),
  reference: z.string().optional(),
});

export interface RowDefaults {
  /** Used when the file has no currency column, or the cell is empty. */
  currency: string;
}

const emptyToNull = (value: string | undefined): string | null =>
  value !== undefined && value.length > 0 ? value : null;

/**
 * Validates one parsed row and converts it to an IncomingTransaction.
 * `rowNumber` is the 1-based line number in the uploaded file.
 */
export function toTransaction(raw: RawRow, rowNumber: number, defaults: RowDefaults): IncomingTransaction {
  const row = rawRowSchema.parse(raw);

  const date = parseStatementDate(row.date);
  if (!date) throw new IngestError("errors.badDate", { row: rowNumber });

  const currency = (row.currency || defaults.currency).toUpperCase();
  if (!isCurrencyCode(currency)) {
    throw new IngestError("errors.badCurrency", { row: rowNumber, value: currency });
  }

  const amount = parseAmount(row.amount, currency);
  if (amount === null) throw new IngestError("errors.badAmount", { row: rowNumber });

  return {
    date,
    amount,
    currency,
    description: normalizeDescription(row.description),
    category: emptyToNull(row.category),
    reference: emptyToNull(row.reference),
  };
}
--- src/ingest/worker.ts
import { config } from "../config";
import { transactionRepo } from "../db/repos/transactionRepo";
import { logger } from "../logger";
import { storage } from "../storage";
import { addDays } from "../util/dates";
import { dedupe, keysFor } from "./dedupe";
import { isIngestError } from "./errors";
import { parseStatement } from "./parser";
import { claimNext, completeJob, failJob, listFailedUploadsBefore, markUploadPurged, type ImportJob } from "./queue";
import { toTransaction } from "./schema";

/** Failed uploads stay in storage this long so the original file can be inspected. */
export const FAILED_UPLOAD_RETENTION_DAYS = 7;

const PURGE_INTERVAL_MS = 60 * 60 * 1000;

const sleep = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));

export async function processJob(job: ImportJob): Promise<void> {
  const { upload } = job;
  const log = logger.child({ jobId: job.id, uploadId: upload.id, attempt: job.attempts });

  const body = await storage.get(upload.key);
  const { rows } = parseStatement(body);

  // The header is line 1 of the file, so data row i is line i + 2.
  const incoming = rows.map((raw, i) => toTransaction(raw, i + 2, { currency: upload.defaultCurrency }));

  let inserted = 0;
  let duplicates = 0;
  if (incoming.length > 0) {
    const dates = incoming.map((t) => t.date).sort();
    const existing = await transactionRepo.listInRange(upload.accountId, dates[0], dates[dates.length - 1]);
    const result = dedupe(incoming, keysFor(existing));
    duplicates = result.duplicates;
    inserted = await transactionRepo.insertMany(upload.accountId, upload.id, result.unique);
  }

  await completeJob(job, { inserted, duplicates });

  // Once the rows are in the ledger the original file is no longer needed.
  await storage.remove(upload.key);
  log.info({ rows: incoming.length, inserted, duplicates }, "import complete");
}

async function runOnce(): Promise<boolean> {
  const job = await claimNext();
  if (!job) return false;

  try {
    await processJob(job);
  } catch (err) {
    // Content problems fail the same way every time; storage and database errors may not.
    const ingest = isIngestError(err) ? err : null;
    const final = await failJob(
      job,
      {
        message: err instanceof Error ? err.message : String(err),
        key: ingest?.key,
        params: ingest?.params,
      },
      ingest === null,
    );
    logger.warn({ err, jobId: job.id, uploadId: job.upload.id, final }, "import failed");
  }
  return true;
}

/** Deletes failed uploads from storage once they are older than the retention period. */
export async function purgeExpiredFailedUploads(now: Date = new Date()): Promise<number> {
  const cutoff = addDays(now, -FAILED_UPLOAD_RETENTION_DAYS);
  const expired = await listFailedUploadsBefore(cutoff);
  for (const upload of expired) {
    await storage.remove(upload.key);
    await markUploadPurged(upload.id);
  }
  if (expired.length > 0) logger.info({ count: expired.length }, "purged expired failed uploads");
  return expired.length;
}

/**
 * Starts `queue.concurrency` polling loops plus the hourly purge. The returned
 * function stops polling and resolves once in-flight jobs have finished.
 */
export function startWorker(): () => Promise<void> {
  let stopping = false;

  const loop = async () => {
    while (!stopping) {
      let didWork = false;
      try {
        didWork = await runOnce();
      } catch (err) {
        logger.error({ err }, "worker loop error");
      }
      if (!didWork) await sleep(config.queue.pollIntervalMs);
    }
  };

  const loops = Array.from({ length: config.queue.concurrency }, () => loop());

  const purgeTimer = setInterval(() => {
    purgeExpiredFailedUploads().catch((err) => logger.error({ err }, "failed upload purge failed"));
  }, PURGE_INTERVAL_MS);

  return async () => {
    stopping = true;
    clearInterval(purgeTimer);
    await Promise.all(loops);
  };
}
